-- Synthetic portal schema reused from the website admin-db harness; no customer/provider data.
create role anon; create role authenticated; create role service_role bypassrls;
 create schema auth;
 create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
 create table auth.users(id uuid primary key, email text,last_sign_in_at timestamptz);
 create type public."Roles" as enum ('User','Admin','Owner');
 create type public.machine_type as enum ('Washer','Dryer');
 create table public.profiles(id uuid primary key references auth.users, email text,full_name text,roles public."Roles" default 'User');
 create table public."Locations"(id bigint generated by default as identity primary key,"Name" text,"Address" text,"Latitude" numeric,"Longitude" numeric);
 create table public."Location_to_Admin"(user_id uuid references public.profiles,location_id bigint references public."Locations",primary key(user_id,location_id));
 create table public.washer_size_rates(id bigint generated by default as identity primary key,location_id bigint references public."Locations",size_label text,capacity_kg bigint,price_cents int,is_active boolean,review_required boolean);
 create table public."Machines"(id bigint generated by default as identity primary key,"Name" text,"Price" numeric,"Runtime" int,"Status" text,"Location_ID" bigint references public."Locations","Machine_type" public.machine_type,"Weight_kg" numeric,washer_size_rate_id bigint references public.washer_size_rates);
 create table public.cortina_machine_config(machine_id bigint primary key references public."Machines",public_machine_token uuid default gen_random_uuid(),nayax_terminal_id text,nayax_uniqr text,pulse_line_number int check(pulse_line_number>0),product_codes jsonb,environment text check(environment in ('sandbox','production')),is_enabled boolean,review_required boolean,
 check(product_codes is null or pulse_line_number is null),
 check(not is_enabled or ((nullif(btrim(nayax_terminal_id),'') is not null or nullif(btrim(nayax_uniqr),'') is not null) and ((product_codes is null and pulse_line_number is not null) or (product_codes is not null and product_codes<>'{}'::jsonb)) and not review_required)));
 create table public.cortina_vend_sessions(id uuid primary key,machine_id bigint references public."Machines",user_id uuid,amount_cents int default 350,currency text default 'USD',payment_method text default 'card',channel text default 'web',status text default 'payment_pending',transaction_id text,stripe_payment_intent_id text,stripe_checkout_session_id text,stripe_refund_id text,failure_message text,completed_at timestamptz,created_at timestamptz default now());
 create table public.transactions(id bigint primary key,user_id uuid references auth.users,amount numeric,description text,created_at timestamptz,cortina_vend_session_id uuid references public.cortina_vend_sessions);
 create table public."Refunds"(refund_id bigint primary key,user_id uuid references auth.users,transaction_id bigint references public.transactions,amount numeric,description text,date timestamptz,status text,admin_note text,resolved_at timestamptz,notification_sent_at timestamptz,resolved_by uuid);
 create table public."Maintenance"(maint_id bigint primary key,user_id uuid references auth.users,category text,description text,created_at timestamptz,location text,image_data text);
 grant usage on schema public,auth to service_role,authenticated;
 grant all on all tables in schema public,auth to service_role;
 grant all on all sequences in schema public to service_role;
