alter table public.cortina_vend_sessions add column stripe_charge_id text, add column wallet_redemption_id bigint, add column nayax_transaction_id text, add column nayax_rrn text;
create table public.cortina_vend_events(id bigint generated always as identity primary key, session_id uuid references public.cortina_vend_sessions, source text, event_type text, event_key text unique, payload jsonb);
create table public.wallet_redemptions(id bigint primary key, amount_cents int, paid_amount_cents int, promo_amount_cents int, status text);
create table public.wallet_loads(id bigint primary key,user_id uuid,amount_cents int,paid_amount_cents int,promo_amount_cents int default 0,stripe_payment_intent_id text unique,stripe_checkout_session_id text unique,stripe_charge_id text unique,stripe_event_id text unique,status text default 'succeeded',created_at timestamptz default now());
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
-- Empty shapes for the legacy reporting suite. The refund integration suite
-- separately installs the actual refund migration and exercises its RPCs.
create schema if not exists private;
create table private.topup_refund_provenance(load_id bigint primary key, location_id bigint,
  payment_succeeded_at timestamptz, stripe_event_id text, livemode boolean);
create table private.voluntary_topup_refunds(id uuid primary key, load_id bigint unique,
  location_id bigint, status text, principal_cents int, stripe_payment_intent_id text,
  livemode boolean, provider_refund_id text, provider_checked_at timestamptz,
  completed_at timestamptz, released_at timestamptz);
